css:
.w-\[280px\] {
  width: 280px;
}
.rounded-lg {
  border-radius: 0.5rem;
}
.border-2 {
  border-width: 2px;
}
.border-solid {
  border-style: solid;
}
.border-\[\#2B3040\] {
  --tw-border-opacity: 1;
  border-color: rgb(43 48 64 / var(--tw-border-opacity));
}
.bg-\[\#222630\] {
  --tw-bg-opacity: 1;
  background-color: rgb(34 38 48 / var(--tw-bg-opacity));
}
.px-4 {
  padding-left: 1rem;
  padding-right: 1rem;
}
.py-3 {
  padding-top: 0.75rem;
  padding-bottom: 0.75rem;
}
.text-white {
  --tw-text-opacity: 1;
  color: rgb(255 255 255 / var(--tw-text-opacity));
}
.outline-none {
  outline: 2px solid transparent;
  outline-offset: 2px;
}
.transition-colors {
  transition-property: color, background-color, border-color, fill, stroke,
    -webkit-text-decoration-color;
  transition-property: color, background-color, border-color,
    text-decoration-color, fill, stroke;
  transition-property: color, background-color, border-color,
    text-decoration-color, fill, stroke, -webkit-text-decoration-color;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 150ms;
}
.duration-100 {
  transition-duration: 100ms;
}
.focus\:border-\[\#596A95\]:focus {
  --tw-border-opacity: 1;
  border-color: rgb(89 106 149 / var(--tw-border-opacity));
}
